using UnityEngine;
namespace DuckGame.Maps.V10 {
[DefaultExecutionOrder(100)]public sealed class UpwardPlayerVisibility:MonoBehaviour {
 public OrbShooter shooter;public Material readyMaterial;Renderer ready;Material originalReadyMaterial;MaterialPropertyBlock originalReadyBlock;bool originalReadyOff;public ShoulderCamera view;public Transform player;public float Visibility{get;private set;}=1;
 SkinnedMeshRenderer[] skins;MaterialPropertyBlock[] original;bool[] originalOff;MaterialPropertyBlock block;
 void Awake(){if(shooter==null||readyMaterial==null||shooter.ReadyVisual==null){Debug.LogError("V10 ready fade references missing",this);enabled=false;return;}ready=shooter.ReadyVisual.GetComponent<Renderer>();originalReadyMaterial=ready.sharedMaterial;originalReadyBlock=new MaterialPropertyBlock();ready.GetPropertyBlock(originalReadyBlock);originalReadyOff=ready.forceRenderingOff;ready.sharedMaterial=readyMaterial;skins=player.GetComponentsInChildren<SkinnedMeshRenderer>();original=new MaterialPropertyBlock[skins.Length];originalOff=new bool[skins.Length];block=new MaterialPropertyBlock();for(int i=0;i<skins.Length;i++){original[i]=new MaterialPropertyBlock();skins[i].GetPropertyBlock(original[i]);originalOff[i]=skins[i].forceRenderingOff;}}
 void OnEnable(){if(ready!=null)ready.sharedMaterial=readyMaterial;}
 void LateUpdate(){Visibility=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(48,68,-view.pitch));for(int i=0;i<skins.Length;i++){skins[i].GetPropertyBlock(block);block.SetFloat("_V10Visibility",Visibility);skins[i].SetPropertyBlock(block);skins[i].forceRenderingOff=originalOff[i]||Visibility<=.001f;}ready.GetPropertyBlock(block);block.SetFloat("_V10Visibility",Visibility);ready.SetPropertyBlock(block);ready.forceRenderingOff=originalReadyOff||Visibility<=.001f;}
 void OnDisable(){if(skins==null)return;for(int i=0;i<skins.Length;i++)if(skins[i]!=null){skins[i].forceRenderingOff=originalOff[i];skins[i].SetPropertyBlock(original[i]);}if(ready!=null){ready.sharedMaterial=originalReadyMaterial;ready.SetPropertyBlock(originalReadyBlock);ready.forceRenderingOff=originalReadyOff;}Visibility=1;}
 void OnGUI(){if(Visibility>.98f||view.ADS<.5f)return;Vector2 p=view.AimViewport;float scale=Screen.height/1080f,x=p.x*Screen.width,y=(1-p.y)*Screen.height;var old=GUI.color;GUI.color=new Color(.03f,.04f,.04f,1-Visibility);GUI.DrawTexture(new Rect(x-3*scale,y-3*scale,6*scale,6*scale),Texture2D.whiteTexture);GUI.color=new Color(.9f,1,1,1-Visibility);GUI.DrawTexture(new Rect(x-1.25f*scale,y-1.25f*scale,2.5f*scale,2.5f*scale),Texture2D.whiteTexture);GUI.color=old;}
}
}
